// Filtering in place - a common trick
out := in[:0]            // zero length, full capacity, SAME array
for _, v := range in {
	if keep(v) {
		out = append(out, v)   // overwrites in[] as it goes
	}
}
// `in` is now scrambled. Fine if you expected it; a bug if you did not.

type P struct{ N int }
m := map[string]P{"a": {N: 1}}

m["a"].N = 2
// ./main.go:8:2: cannot assign to struct field m["a"].N in map

// Either store pointers...
mp := map[string]*P{"a": {N: 1}}
mp["a"].N = 2            // fine

// ...or read, modify, write back
p := m["a"]
p.N = 2
m["a"] = p

type Item struct{ Done bool }
items := []Item{{}, {}}

for _, it := range items {
	it.Done = true          // modifies a copy, thrown away
}
fmt.Println(items)              // [{false} {false}]

for i := range items {
	items[i].Done = true    // index in - this works
}

keys := make([]string, 0, len(m))
for k := range m {
	keys = append(keys, k)
}
sort.Strings(keys)

for _, k := range keys {
	fmt.Println(k, m[k])
}

